if pin is None and not fast_disk:
    loaded_pin = comfy.pinned_memory.get_pin(s, subset="weights-loaded")
    if loaded_pin is not None or signature is not None:
        subset = "weights-loaded"
        pin = loaded_pin
if pin is not None:
